-- =========================================================================
-- Behavioral Rhythm, Circadian Alignment & Productivity Prediction
-- Supabase Schema & Seed Data Setup
-- =========================================================================

-- 1. Ensure Tables Exist
CREATE TABLE IF NOT EXISTS public.profiles (
  id uuid NOT NULL,
  display_name text,
  created_at timestamp with time zone DEFAULT now(),
  age integer,
  CONSTRAINT profiles_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS public.daily_logs (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id uuid,
  date date NOT NULL,
  last_unlock_prev_night time without time zone,
  first_unlock_morning time without time zone,
  sleep_duration_estimate_mins integer,
  total_screen_time_mins integer,
  unlock_count integer,
  avg_session_length_mins double precision,
  dominant_app_category text,
  step_count integer,
  active_minutes integer,
  primary_activity text,
  away_from_home_mins integer,
  calendar_event_count integer,
  weather_condition text,
  day_of_week text,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT daily_logs_pkey PRIMARY KEY (id),
  CONSTRAINT daily_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.predictions (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id uuid,
  date date NOT NULL,
  is_predictive boolean,
  confidence_score double precision,
  reason_tags text[],
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT predictions_pkey PRIMARY KEY (id),
  CONSTRAINT predictions_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS public.feedback (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id uuid,
  date date NOT NULL,
  rating integer CHECK (rating >= 0 AND rating <= 5),
  note text,
  submitted_at timestamp with time zone DEFAULT now(),
  CONSTRAINT feedback_pkey PRIMARY KEY (id),
  CONSTRAINT feedback_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE CASCADE
);

-- 2. Configure Row Level Security (RLS) with Public/Anon SELECT Policies
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.daily_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.predictions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.feedback ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow anon select profiles" ON public.profiles;
CREATE POLICY "Allow anon select profiles" ON public.profiles FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow anon select daily_logs" ON public.daily_logs;
CREATE POLICY "Allow anon select daily_logs" ON public.daily_logs FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow anon select predictions" ON public.predictions;
CREATE POLICY "Allow anon select predictions" ON public.predictions FOR SELECT USING (true);

DROP POLICY IF EXISTS "Allow anon select feedback" ON public.feedback;
CREATE POLICY "Allow anon select feedback" ON public.feedback FOR SELECT USING (true);

-- 3. Seed Users
ON CONFLICT (id) DO UPDATE SET display_name = EXCLUDED.display_name, age = EXCLUDED.age;

